using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using NomadNet;

namespace NomadNet.Tests;

[Trait("Category", "Unit")]
public sealed class NomadNetMicronGrammarTests
{
    [Fact, Trait("TestId", "T860")]
    public void T860PinnedLineAndInlineCorpusMatchesActualPrimary()
    {
        // Generated by executing primary 1.4.4 f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2.
        // The generator and generated fixture retain the source hash and shell shim disclosure.
        using var vectors = JsonDocument.Parse(NomadNetMicronGrammarVectors.Json);
        Assert.Equal("f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2", vectors.RootElement.GetProperty("revision").GetString());
        foreach (var item in vectors.RootElement.GetProperty("cases").EnumerateArray())
        {
            var name = item.GetProperty("name").GetString();
            if (item.TryGetProperty("error", out var error))
            {
                Assert.Equal("fold-empty-formatting-heading", name);
                Assert.Equal("TypeError", error.GetString());
                Assert.Equal("object of type 'NoneType' has no len()", item.GetProperty("message").GetString());
                // The primary crashes on an empty styled heading; native recovery is an explicit safety difference.
                var recovered = MicronText.Render(Encoding.UTF8.GetBytes(item.GetProperty("source").GetString()!));
                Assert.Single(recovered.Folds);
                Assert.EndsWith("end", recovered.Present(new NomadNetSettings()));
                continue;
            }
            var page = MicronText.Render(Encoding.UTF8.GetBytes(item.GetProperty("source").GetString()!));
            var expected = item.GetProperty("observed");
            var text = page.Text;
            foreach (var (field, index) in page.Fields.Select((field, index) => (field, index)))
                text = text.Replace($"[field {index + 1} {field.Name}: " +
                    (field.Kind == "field" ? field.DisplayValue : (field.Selected ? "[x] " : "[ ] ") + field.Label) + "]", "",
                    StringComparison.Ordinal);
            text = Regex.Replace(text, @"\[\d+\] ", "");
            var rawRows = text.Split('\n');
            foreach (var fold in page.Folds)
                rawRows[fold.Row] = (fold.Collapsed ? fold.ClosedGlyph : fold.OpenGlyph) + " " + rawRows[fold.Row];
            text = string.Join('\n', rawRows);
            text = string.Join('\n', text.Split('\n').Select(row => row.TrimStart(' '))).TrimEnd();
            var primary = string.Join('\n', expected.GetProperty("text").GetString()!.Split('\n').Select(row => row.TrimStart(' '))).TrimEnd();
            Assert.True(primary == text, $"{name}: expected <{primary}>; actual <{text}>");
            Assert.Equal(expected.GetProperty("fields").GetArrayLength(), page.Fields.Count);
            foreach (var (field, index) in page.Fields.Select((field, index) => (field, index)))
            {
                var reference = expected.GetProperty("fields")[index];
                Assert.Equal(reference.GetProperty("kind").GetString(), field.Kind);
                Assert.Equal(reference.GetProperty("name").GetString(), field.Name);
                Assert.Equal(reference.GetProperty("value").GetString(), field.Value);
                if (field.Kind == "field")
                {
                    Assert.Equal(reference.GetProperty("masked").GetBoolean(), field.Masked);
                    Assert.Equal(reference.GetProperty("rows").GetInt32(), field.Rows);
                }
                else
                {
                    Assert.False(field.Masked);
                    Assert.Equal(reference.GetProperty("selected").GetBoolean(), field.Selected);
                }
            }
            Assert.Equal(expected.GetProperty("anchors").EnumerateObject().Select(anchor => (anchor.Name, anchor.Value.GetInt32())),
                page.Anchors.Select(anchor => (anchor.Key, anchor.Value)));
        }
    }

    [Fact, Trait("TestId", "T861")]
    public void T861ClosedMalformedLinksDoNotExposeTargetsOrBecomeActions()
    {
        var page = MicronText.Render("a`[]b`[label`]c`[a`b`c`d]d`[broken\nend`"u8);
        Assert.Empty(page.Links);
        Assert.Equal("abcdbroken\nend", page.Text);
        Assert.Empty(MicronText.Render(">Empty\n<##comment\n"u8).Fields);
    }

    [Fact, Trait("TestId", "T862")]
    public void T862PendingAnchorsBindTheNextVisibleRowAndResetTerminatesFolds()
    {
        var page = MicronText.Render("`:pending\n#comment\n`->Fold\nhidden\n<visible\n"u8);
        Assert.Equal(0, page.Anchors["pending"]);
        Assert.DoesNotContain("hidden", page.DisplayText);
        Assert.Contains("visible", page.DisplayText);
        Assert.Equal("Fold\nhidden\nvisible", page.AtAnchor("pending"));
        page.ToggleFold(1);
        Assert.Contains("hidden", page.DisplayText);
        page.ToggleFold(1);
        Assert.DoesNotContain("hidden", page.DisplayText);
        var reset = MicronText.Render(">>Heading\n<<<#ignored\nvisible"u8);
        Assert.EndsWith("\nvisible", reset.Text);
        var image = MicronText.Render("`->Fold\nhidden\n<`(alt`/media/synthetic.webp)"u8);
        Assert.Contains("[image 1:", image.DisplayText);
        Assert.DoesNotContain("hidden", image.DisplayText);
        var partial = MicronText.Render("`->Fold\nhidden\n<`{/page/update.mu}"u8);
        Assert.Contains("[partial 1:", partial.DisplayText);
        Assert.DoesNotContain("hidden", partial.DisplayText);
    }

    [Fact, Trait("TestId", "T863")]
    public void T863TablesBufferUntilCloseAndRetainOriginalActionableCells()
    {
        Assert.Empty(MicronText.Render("`t\n| secret | discarded |\n|--|--|"u8).Text);
        var page = MicronText.Render("`t\n| Name | Action |\n|---|---|\n| Original | `[Go`/page/original.mu] |\n`t"u8);
        Assert.Equal("/page/original.mu", Assert.Single(page.Links).Target);
        Assert.Contains("Original", page.DisplayText);
        Assert.DoesNotContain("|---|", page.DisplayText);
        Assert.Equal(page.Text, page.DisplayText);
    }

    [Fact, Trait("TestId", "T864")]
    public void T864GrammarBoundsAndInvalidUtf8FailExplicitly()
    {
        Assert.Throws<DecoderFallbackException>(() => MicronText.Render(new byte[] { 0xff }));
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes(new string('>', 257) + "heading")));
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes(
            string.Join('\n', Enumerable.Repeat("`(alt`/media/image.webp)", 129)))));
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes(
            string.Join('\n', Enumerable.Repeat("`{/page/update.mu}", 65)))));
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes(
            "`t\n" + string.Join('\n', Enumerable.Repeat("| value |", 4097)) + "\n`t")));
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes(
            string.Join('\n', Enumerable.Repeat("`->fold", 257)))));
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes(
            string.Join('\n', Enumerable.Range(0, 2049).Select(index => "`:anchor" + index)))));
        Assert.Throws<InvalidDataException>(() => MicronText.Render("`t513\n| a |\n|--|\n`t"u8));
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes(
            "`t\n|" + string.Join('|', Enumerable.Repeat("cell", 129)) + "|\n|--|\n`t")));
        var expansiveTable = "`t\n" + new string('|', 129) + "\n|--|\n" +
            string.Join('\n', Enumerable.Repeat("|x|", 4000)) + "\n`t\n";
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes(expansiveTable + expansiveTable)));
        Assert.Equal(128, MicronText.Render(Encoding.UTF8.GetBytes(
            string.Join('\n', Enumerable.Repeat("`(alt`/media/synthetic.webp)", 128)))).Media.Count);
        Assert.Equal(64, MicronText.Render(Encoding.UTF8.GetBytes(
            string.Join('\n', Enumerable.Repeat("`{/page/update.mu}", 64)))).Partials.Count);
        Assert.Equal(256, MicronText.Render(Encoding.UTF8.GetBytes(
            string.Join('\n', Enumerable.Repeat("`->fold", 256)))).Folds.Count);
        Assert.Equal("healthy", MicronText.Render("healthy"u8).Text);
    }

    [Fact, Trait("TestId", "T865")]
    public void T865PartialIdsAndRefreshMatchActualPinnedParsePartial()
    {
        using var vectors = JsonDocument.Parse(NomadNetMicronGrammarVectors.Json);
        foreach (var item in vectors.RootElement.GetProperty("partials").EnumerateArray())
        {
            var page = MicronText.Render(Encoding.UTF8.GetBytes("`{" + item.GetProperty("source").GetString()));
            var reference = item.GetProperty("observed");
            if (reference.ValueKind == JsonValueKind.Null)
            {
                Assert.Empty(page.Partials);
                Assert.Contains("[invalid partial]", page.Text);
                continue;
            }
            var partial = Assert.Single(page.Partials);
            Assert.Equal(reference.GetProperty("id").GetString(), partial.Id);
            Assert.Equal(reference.GetProperty("target").GetString(), partial.Target);
            Assert.Equal(reference.GetProperty("fields").GetString(), partial.Fields);
            Assert.Equal(reference.GetProperty("refresh").ValueKind == JsonValueKind.Null ? (double?)null :
                reference.GetProperty("refresh").GetDouble(), partial.RefreshSeconds);
        }
    }

    [Fact, Trait("TestId", "T875")]
    public void T875StyleStateAlignmentHeadingAndTableControlsMatchExecutedPrimary()
    {
        using var vectors = JsonDocument.Parse(NomadNetMicronGrammarVectors.Json);
        foreach (var item in vectors.RootElement.GetProperty("cases").EnumerateArray().Where(item =>
            item.GetProperty("name").GetString() is { } name &&
            (name.StartsWith("style-", StringComparison.Ordinal) || name.StartsWith("align-", StringComparison.Ordinal) ||
             name.StartsWith("heading-latched", StringComparison.Ordinal) || name.StartsWith("heading-explicit", StringComparison.Ordinal) ||
             name.StartsWith("table-", StringComparison.Ordinal))))
        {
            var page = MicronText.Render(Encoding.UTF8.GetBytes(item.GetProperty("source").GetString()!));
            var observed = item.GetProperty("observed").GetProperty("styled");
            if (observed.GetArrayLength() == 0) continue;
            Assert.Equal(observed.GetArrayLength(), page.RowStyles.Count);
            var row = 0;
            foreach (var expectedRow in observed.EnumerateArray())
            {
                Assert.Equal(expectedRow.GetProperty("align").GetString(), page.RowStyles[row].Alignment);
                var column = 0;
                foreach (var part in expectedRow.GetProperty("spans").EnumerateArray())
                {
                    var text = part.GetProperty("text").GetString()!;
                    var name = part.GetProperty("style").GetString() ?? "";
                    for (var index = 0; index < text.Length; index++)
                    {
                        var style = Assert.Single(page.Styles, style => style.Row == row &&
                            column + index >= style.Column && column + index < style.Column + style.Length).Style;
                        Assert.Equal(name.Contains(",bold", StringComparison.Ordinal), style.Bold);
                        Assert.Equal(name.Contains(",underline", StringComparison.Ordinal), style.Underline);
                        Assert.Equal(name.Contains(",italics", StringComparison.Ordinal), style.Italic);
                        var colors = name.Split('_');
                        var heading = page.RowStyles[row].HeadingDepth != 0;
                        Assert.Equal(heading, style.Heading);
                        if (!heading && colors.Length >= 3)
                        {
                            Assert.Equal(colors[1] == "222" ? null : colors[1], style.Foreground);
                            Assert.Equal(colors[2] == "default" ? null : colors[2], style.Background);
                        }
                    }
                    column += text.Length;
                }
                row++;
            }
        }
        var source = vectors.RootElement.GetProperty("sourceBytes").GetProperty("nomadnet/ui/textui/MicronParser.py");
        Assert.Equal("995a8fd8883ec57cd173d117b6758447e508ca2ddf96d8521260cc70e18a8e4e", source.GetProperty("gitBlobSha256").GetString());
        Assert.True(source.GetProperty("equalAfterCrLfNormalization").GetBoolean());
    }

    [Fact, Trait("TestId", "T876")]
    public void T876OriginalStyledOutputHonorsAlignmentColorModesAndSafePlainFallback()
    {
        var page = MicronText.Render("`!`_`*`FT123456`BT654321marked`` plain\n`ccenter\n`rright\n`aend"u8);
        var settings = new NomadNetSettings { ColorMode = "24bit" };
        var output = page.Present(settings, true, 20);
        Assert.Contains("\u001b[1;4;3;38;2;18;52;86;48;2;101;67;33mmarked\u001b[0m plain", output);
        Assert.Contains("\n       center\n               right\nend", output);
        Assert.DoesNotContain('\u001b', page.Present(settings, false));
        settings.ColorMode = "monochrome";
        Assert.DoesNotContain('\u001b', page.Present(settings, true));
        foreach (var mode in new[] { "16", "88", "256" })
        {
            settings.ColorMode = mode;
            var styled = page.Present(settings, true);
            Assert.Contains("\u001b[1;4;3;", styled);
            Assert.DoesNotContain(";2;18;52;86", styled);
        }
        Assert.Equal("a😀\nb", MicronText.Render("a😀b"u8).Present(settings, false, 2));
        Assert.Equal("808080", MicronStyle.Rgb("g50"));
        Assert.Null(MicronStyle.Rgb("badcolor"));
        Assert.DoesNotContain('\u001b', MicronText.Render("unsafe\u001b[31m\u202Etext"u8).Present(settings, false));
        var fold = MicronText.Render("#!fold OPEN SHUT\n`->Fold\nhidden\n<end"u8);
        Assert.StartsWith("SHUT Fold", fold.Present(settings, false));
        fold.ToggleFold(1);
        Assert.StartsWith("OPEN Fold\nhidden", fold.Present(settings, false));
        var unicodeTable = MicronText.Render("`t8\n| A |\n|--|\n| 😀😀😀😀 |\n`t"u8);
        _ = new UTF8Encoding(false, true).GetBytes(unicodeTable.Text);
        Assert.Contains("…", unicodeTable.Text);
    }

    [Fact, Trait("TestId", "T877")]
    public void T877StylesSurviveMutableFieldsPartialCompositionAndAnchorViews()
    {
        var root = MicronText.Render("`!`<input`old>`! tail\n`{/page/update.mu}"u8);
        var child = MicronText.Render("`:inside\n`_child`_ `[Go`#inside]"u8);
        var page = NomadNetMicronComposition.Compose(root, new Dictionary<NomadNetPagePartial, NomadNetRenderedPage>
            { [root.Partials[0]] = child });
        page.SetField(1, "longer changed value");
        var settings = new NomadNetSettings { ColorMode = "24bit" };
        var rendered = page.Present(settings, true, 120);
        Assert.Contains("\u001b[1m[field 1 input: longer changed value]\u001b[0m tail", rendered);
        Assert.Contains("\u001b[4mchild\u001b[0m", rendered);
        Assert.Equal(1, page.Anchors["inside"]);
        Assert.DoesNotContain("input", page.Present(settings, true, 120, startRow: page.Anchors["inside"]));
        Assert.Equal("#inside", Assert.Single(page.Links).Target);
    }

    [Fact, Trait("TestId", "T878")]
    public void T878ImagePropertiesAndBoundedLayoutMatchActualPrimarySettersAndSizing()
    {
        using var vectors = JsonDocument.Parse(NomadNetMicronGrammarVectors.Json);
        foreach (var item in vectors.RootElement.GetProperty("images").EnumerateArray())
        {
            var image = Assert.Single(MicronText.Render(Encoding.UTF8.GetBytes("`(" + item.GetProperty("source").GetString())).Media);
            Assert.Equal(item.GetProperty("width").ValueKind == JsonValueKind.Null ? null : item.GetProperty("width").ToString(), image.Width);
            Assert.Equal(item.GetProperty("height").ValueKind == JsonValueKind.Null ? null : item.GetProperty("height").ToString(), image.Height);
            Assert.Equal(item.GetProperty("align").GetString() switch { "<" => "left", ">" => "right", _ => "center" }, image.Alignment);
            Assert.Equal((item.GetProperty("display")[0].GetInt32(), item.GetProperty("display")[1].GetInt32()),
                image.Layout(80, 40, 40, 32, 20));
        }
        Assert.Throws<InvalidDataException>(() => MicronText.Render("`(alt`w=4097`/image.webp)"u8));
        Assert.Throws<InvalidDataException>(() => MicronText.Render("`(alt`h=1001%`/image.webp)"u8));
        Assert.Throws<ArgumentOutOfRangeException>(() => new NomadNetPageMedia("", "").Layout(1, 1, 161));
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes("#!fold " + new string('x', 33))));
        Assert.Throws<InvalidDataException>(() => MicronText.Render(Encoding.UTF8.GetBytes(string.Concat(Enumerable.Repeat("`!x", 65537)))));
        Assert.Equal("healthy", MicronText.Render("healthy"u8).Text);
    }

    [Fact, Trait("TestId", "T880")]
    public void T880ConversationAndRrcActivateAllowedStylesButRetainPrimaryAlignmentSuppression()
    {
        var settings = new NomadNetSettings { ColorMode = "24bit", RrcRenderMarkdown = false, RrcRenderMicron = true };
        Assert.Contains("\u001b[1mbold\u001b[0m", NomadNetPresentation.Conversation("**bold** and *italic*", 2, settings, true));
        Assert.Contains("\u001b[3mitalic\u001b[0m", NomadNetPresentation.Conversation("**bold** and *italic*", 2, settings, true));
        Assert.DoesNotContain('\u001b', NomadNetPresentation.Conversation("**literal**", null, settings, true));
        using var fixture = JsonDocument.Parse(NomadNetMicronGrammarVectors.Json);
        var reference = fixture.RootElement.GetProperty("consumerControls")[2];
        var message = new RrcChatMessage("msg", "room", new string('1', 32), "Peer",
            reference.GetProperty("source").GetString()!, 100000, false);
        Assert.Equal(reference.GetProperty("rrcMicronOnly").GetProperty("text").GetString(),
            string.Concat(NomadNetRrcPresentation.Style(message, settings, "", "").Body.Select(span => span.Text)));
        var output = NomadNetRrcPresentation.RenderStream(message, settings, "", "", ansi: true);
        Assert.Contains("\u001b[1mbold\u001b[0m", output);
        Assert.Contains("\u001b[4munder\u001b[0m", output);
        Assert.Contains("\u001b[3mitalic\u001b[0m", output);
        Assert.Contains("\u001b[38;2;18;52;86mcolor\u001b[0m", output);
        Assert.Contains("\u001b[48;2;101;67;33mback\u001b[0m", output);
        Assert.Equal("Right Center Left", NomadNetPresentation.Rrc("`rRight `cCenter `lLeft", false, true));
        Assert.DoesNotContain('\u001b', NomadNetRrcPresentation.RenderStream(message, settings, "", ""));
        settings.ColorMode = "monochrome";
        Assert.DoesNotContain('\u001b', NomadNetRrcPresentation.RenderStream(message, settings, "", "", ansi: true));
    }
}
